import jdk.jfr.consumer.*;import java.nio.file.*;import java.util.*;
public class Analyze {
 static Map<String,Long> leaves=new HashMap<>(),inc=new HashMap<>(),ac=new HashMap<>(),as=new HashMap<>(),cat=new HashMap<>();
 static String[][] rules={{"writer","BinaryQueryResultWriter","CharsetEncoder","UTF_8$Encoder"},{"row_snapshot","SailResultValueExtractor$1.snapshot","SailResultValueExtractor$1.lambda$snapshot"},{"value_projection_memo","NativeValueMemo","NativeProjectedBindingSet","ValueStore.getLazyValue"},{"value_decode","ValueStore.data2","LmdbLiteral.init","LmdbIRI.init"},{"value_lifetime","RepositoryValueIteration","ValueResolutionScope","executeObservedRead","executeTrackedRead"},{"distinct","NativeDistinct","PrimitiveTupleTable","NativeExpressionDomain"},{"query_kernel","IrKernel_","KernelRuntime","LmdbFusedSip","NativeRowsStep","RowState"},{"harness","ProfileComparisonBenchmark"}};
 static void add(Map<String,Long> m,String k,long v){m.merge(k,v,Long::sum);}
 static void dump(String title,Map<String,Long> m,long total,int n){System.out.println("\n"+title);m.entrySet().stream().sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(n).forEach(e->System.out.printf("%12d %6.2f%% %s%n",e.getValue(),100.0*e.getValue()/Math.max(1,total),e.getKey()));}
 public static void main(String[] a)throws Exception{long samples=0,alloc=0;try(var f=new RecordingFile(Path.of(a[0]))){while(f.hasMoreEvents()){var e=f.readEvent();String type=e.getEventType().getName();boolean cpu=type.equals("jdk.ExecutionSample")||type.equals("jdk.NativeMethodSample"), al=type.equals("jdk.ObjectAllocationSample");if(!cpu&&!al)continue;var thread=cpu?e.getThread("sampledThread"):e.getThread();if(thread==null||!thread.getJavaName().equals("main"))continue;List<String> ns=new ArrayList<>();if(e.getStackTrace()!=null)for(var fr:e.getStackTrace().getFrames()){var m=fr.getMethod();ns.add(m.getType().getName()+"."+m.getName());}if(cpu){samples++;if(!ns.isEmpty())add(leaves,ns.get(0),1);for(var n:new HashSet<>(ns))add(inc,n,1);String label="other";outer:for(String n:ns)for(var r:rules)for(int j=1;j<r.length;j++)if(n.contains(r[j])){label=r[0];break outer;}add(cat,label,1);}else{long w=e.getLong("weight");alloc+=w;add(ac,e.getClass("objectClass").getName(),w);String frame=ns.stream().filter(n->n.startsWith("org.eclipse.rdf4j")).findFirst().orElse(ns.isEmpty()?"unknown":ns.get(0));add(as,frame,w);}}}System.out.printf("mainThreadCpuSamples=%d sampledAllocationWeight=%d%n",samples,alloc);dump("NEAREST MATCHING STACK CATEGORIES",cat,samples,30);dump("LEAF",leaves,samples,40);dump("INCLUSIVE (overlapping)",inc,samples,70);dump("ALLOCATION CLASSES",ac,alloc,30);dump("ALLOCATION FIRST RDF4J FRAME",as,alloc,40);}
}
